xhtml:div.script:
(() => {
  const DB_NAME = "fieldnote-launcher";
  const STORE_NAME = "files";
  const DB_VERSION = 1;
  const dbPromise = new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        const store = db.createObjectStore(STORE_NAME, { keyPath: "id" });
        store.createIndex("addedAt", "addedAt");
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
  const library = document.getElementById("library");
  const input = document.getElementById("file-input");
  const status = document.getElementById("status");
  let noticeTimer;
  const XHTML_NS = "http://www.w3.org/1999/xhtml";

  function createHtmlElement(tagName) {
    return document.createElementNS(XHTML_NS, tagName);
  }

  function notify(message) {
    status.textContent = message;
    status.classList.add("show");
    clearTimeout(noticeTimer);
    noticeTimer = setTimeout(() => status.classList.remove("show"), 3600);
  }

  function formatSize(bytes) {
    if (bytes < 1024) return `${bytes} B`;
    const units = ["KB", "MB", "GB", "TB"];
    let size = bytes / 1024;
    let unit = 0;
    while (size >= 1024 && unit < units.length - 1) {
      size /= 1024;
      unit += 1;
    }
    return `${size.toFixed(size >= 100 ? 0 : 1)} ${units[unit]}`;
  }

  function formatDate(timestamp) {
    return new Intl.DateTimeFormat(undefined, { month: "short", day: "numeric", year: "numeric" }).format(timestamp);
  }

  function iconMarkup() {
    return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 3h8l4 4v14H6zM14 3v5h5M9 13h6M9 17h6" /></svg>';
  }

  function requestResult(request) {
    return new Promise((resolve, reject) => {
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  }

  async function allFiles() {
    const db = await dbPromise;
    const transaction = db.transaction(STORE_NAME, "readonly");
    return requestResult(transaction.objectStore(STORE_NAME).getAll());
  }

  async function writeFile(record) {
    const db = await dbPromise;
    const transaction = db.transaction(STORE_NAME, "readwrite");
    transaction.objectStore(STORE_NAME).put(record);
    return new Promise((resolve, reject) => {
      transaction.oncomplete = resolve;
      transaction.onerror = () => reject(transaction.error);
      transaction.onabort = () => reject(transaction.error || new Error("Storage transaction aborted"));
    });
  }

  async function deleteFile(id) {
    const db = await dbPromise;
    const transaction = db.transaction(STORE_NAME, "readwrite");
    transaction.objectStore(STORE_NAME).delete(id);
    return new Promise((resolve, reject) => {
      transaction.oncomplete = resolve;
      transaction.onerror = () => reject(transaction.error);
    });
  }

  async function clearFiles() {
    const db = await dbPromise;
    const transaction = db.transaction(STORE_NAME, "readwrite");
    transaction.objectStore(STORE_NAME).clear();
    return new Promise((resolve, reject) => {
      transaction.oncomplete = resolve;
      transaction.onerror = () => reject(transaction.error);
    });
  }

  function makeCard(record, index) {
    const card = createHtmlElement("article");
    card.className = "file-card";
    card.style.animationDelay = `${Math.min(index * 35, 210)}ms`;

    const top = createHtmlElement("div");
    top.className = "file-top";
    const icon = createHtmlElement("div");
    icon.className = "file-icon";
    icon.innerHTML = iconMarkup();
    const fileType = createHtmlElement("span");
    fileType.className = "file-type";
    fileType.textContent = (record.name.split(".").pop() || "file").slice(0, 12).toUpperCase();
    icon.append(fileType);
    const remove = createHtmlElement("button");
    remove.className = "icon-button";
    remove.type = "button";
    remove.title = `Delete ${record.name} from cache`;
    remove.setAttribute("aria-label", remove.title);
    remove.innerHTML = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M10 11v6M14 11v6M5 7l1 14h12l1-14M9 7V4h6v3" /></svg>';
    remove.addEventListener("click", async () => {
      await deleteFile(record.id);
      await render();
      notify("Removed from your local library.");
    });
    top.append(icon, remove);

    const name = createHtmlElement("h3");
    name.className = "file-name";
    name.title = record.name;
    name.textContent = record.name;
    const meta = createHtmlElement("div");
    meta.className = "file-meta";
    const size = createHtmlElement("span");
    size.textContent = formatSize(record.size);
    const date = createHtmlElement("span");
    date.textContent = formatDate(record.addedAt);
    meta.append(size, date);
    const launch = createHtmlElement("button");
    launch.className = "launch-button";
    launch.type = "button";
    launch.innerHTML = 'Launch <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 17 17 7M7 7h10v10" /></svg>';
    launch.addEventListener("click", () => {
      const tab = window.open("about:blank", "_blank");
      if (!tab) {
        notify("Allow pop-ups for this page to launch a file.");
        return;
      }
      const objectUrl = URL.createObjectURL(record.blob);
      tab.opener = null;
      tab.location.replace(objectUrl);
    });
    card.append(top, name, meta, launch);
    return card;
  }

  async function render() {
    const files = (await allFiles()).sort((left, right) => right.addedAt - left.addedAt);
    const bytes = files.reduce((total, record) => total + record.size, 0);
    document.getElementById("file-count").textContent = String(files.length);
    document.getElementById("item-count").textContent = `${String(files.length).padStart(2, "0")} ITEMS`;
    document.getElementById("total-size").textContent = formatSize(bytes);
    library.replaceChildren();
    if (files.length === 0) {
      const empty = createHtmlElement("div");
      empty.className = "empty";
      empty.innerHTML = '<div class="empty-inner"><div class="empty-mark"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 16V4m0 0L7 9m5-5 5 5M5 15v5h14v-5" /></svg></div><h3>Your shelf is waiting.</h3><p>Open the shared folder, download what you need, then add those files here.</p><p class="drop-hint">You can also drop files anywhere on this window.</p></div>';
      library.append(empty);
      return;
    }
    files.forEach((record, index) => library.append(makeCard(record, index)));
  }

  async function importFiles(fileList) {
    const files = Array.from(fileList || []);
    if (!files.length) return;
    let added = 0;
    for (const file of files) {
      const id = typeof crypto.randomUUID === "function" ? crypto.randomUUID() : `${Date.now()}-${Math.random().toString(16).slice(2)}`;
      try {
        await writeFile({ id, name: file.name, size: file.size, type: file.type || "application/octet-stream", addedAt: Date.now(), blob: file });
        added += 1;
      } catch (error) {
        const reason = error && error.name === "QuotaExceededError" ? "Browser storage is full. Delete cached files and try again." : "Could not save a file to browser storage.";
        notify(reason);
        break;
      }
    }
    await render();
    if (added) notify(`${added} file${added === 1 ? "" : "s"} added to your local library.`);
  }

  document.getElementById("add-button").addEventListener("click", () => input.click());
  input.addEventListener("change", async () => {
    await importFiles(input.files);
    input.value = "";
  });
  document.getElementById("clear-button").addEventListener("click", async () => {
    const files = await allFiles();
    if (!files.length) {
      notify("Your local library is already empty.");
      return;
    }
    if (!window.confirm(`Delete all ${files.length} cached file${files.length === 1 ? "" : "s"}? This cannot be undone.`)) return;
    await clearFiles();
    await render();
    notify("All cached files have been deleted.");
  });

  window.addEventListener("dragover", event => {
    event.preventDefault();
    document.getElementById("shell").classList.add("dragging");
  });
  window.addEventListener("dragleave", event => {
    if (event.relatedTarget === null) document.getElementById("shell").classList.remove("dragging");
  });
  window.addEventListener("drop", async event => {
    event.preventDefault();
    document.getElementById("shell").classList.remove("dragging");
    await importFiles(event.dataTransfer.files);
  });

  const svg = document.documentElement;
  const frame = document.getElementById("app-frame");
  function sizeFrame() {
    const width = window.innerWidth;
    const height = window.innerHeight;
    svg.setAttribute("viewBox", `0 0 ${width} ${height}`);
    frame.setAttribute("width", String(width));
    frame.setAttribute("height", String(height));
  }
  window.addEventListener("resize", sizeFrame);
  sizeFrame();

  dbPromise.then(() => render()).catch(error => {
    document.getElementById("connection-label").textContent = "storage unavailable";
    notify(`IndexedDB could not start: ${error.message || "browser storage is unavailable"}`);
  });
})();
